  const [pinnedRegions, setPinnedRegions] = useState(
    () => { try { return JSON.parse(localStorage.getItem("pinnedRegions") || "[]"); } catch { return []; } }
  );
  const [populationData, setPopulationData] = useState({});
  const [dimOverlay, setDimOverlay] = useState(null);
  const [factionSearch, setFactionSearch] = useState("");
  const [classicToImperial, setClassicToImperial] = useState(null); // city mapping
  const [classicVictory, setClassicVictory] = useState(null); // parsed classic victory conditions
  const [portedVictory, setPortedVictory] = useState(null); // ported conditions (null = not computed)
  const [showPortedVictory, setShowPortedVictory] = useState(false); // toggle ported vs original
  const [savedOriginalVictory, setSavedOriginalVictory] = useState(null); // backup of original
  const [legendSearch, setLegendSearch] = useState("");
  const [exportConfirm, setExportConfirm] = useState(false);

  // ── Live log watcher state ──
  const [liveLogActive, setLiveLogActive] = useState(false);
  const [liveLogEvents, setLiveLogEvents] = useState([]); // [{type, text, turn, ts}]
  const [liveLogTurn, setLiveLogTurn] = useState(null); // {turn, year, season, faction}
  // Number of Turn-End events seen since activation. Used to gate save-derived
  // building overrides — the heuristic save parser produces false positives
  // when the game is still on turn 0, so only trust it once a turn has ended.
  const [liveTurnsEnded, setLiveTurnsEnded] = useState(0);
  // Player's faction for live mode. Persisted so repeat launches remember.
  const [playerFaction, setPlayerFaction] = useState(() => {
    try { return localStorage.getItem("playerFaction") || null; } catch { return null; }
  });
  // Ref mirror so the save-snapshot handler (inside an effect) always sees the
  // current playerFaction without re-subscribing on every change.
  const playerFactionRef = useRef(playerFaction);
  useEffect(() => { playerFactionRef.current = playerFaction; }, [playerFaction]);
  // [diag] NON-LIVE / STARTING-STATE self-check. Runs once when the starting
  // region/commander data is assembled (descr_strat characters loaded AND no
  // live save overriding). Mirrors the live `[diag]` in main.js but for the
  // non-live resolvers: a commander-card portrait resolves from statsCache by
  // the SAME `fn|ln|fac` key the family tree uses (see resolveNonLiveCommanderInfo
  // + FamilyTree.js coordToSave `name:` keys), so a null there means the renderer
  // hash pool fires (the nomad-faces class). One concise [diag] line per assembled
  // starting state into provincia.log (which captures console). Read-only; never
  // throws into render. Declared AFTER playerFaction to avoid a render-time TDZ.
  const nonLiveDiagKeyRef = useRef(null);
  useEffect(() => {
    try {
      // Only when in non-live mode (no live save armies) and we have starting
      // characters. saveLiveArmies present ⇒ the live [diag] already covers it.
      if (saveLiveArmies && saveLiveArmies.length) return;
      const chars = Array.isArray(startingCharactersFromMod) ? startingCharactersFromMod : null;
      if (!chars || chars.length === 0) return;
      // Debounce: only re-run when the inputs that affect resolution change.
      const sc = statsCache || {};
      const key = `${chars.length}|${Object.keys(sc).length}|${playerFaction || ""}`;
      if (nonLiveDiagKeyRef.current === key) return;
      nonLiveDiagKeyRef.current = key;

      // 0.9.784: the family-tree resolution map is the ENGINE-EXACT portrait map
      // (v1PortraitsByCoord coords + descr_strat-coord-joined name keys + the
      // persisted statsCache) — the SAME map the commander cards now resolve from
      // (see buildNonLivePortraitMap / resolveNonLiveCommanderInfo). Cross-check
      // the card's pick against THIS (not a statsCache-only map, which is what
      // let the gate falsely PASS while the cards still hash-pooled the royal
      // family). The new commander sub-check below exercises the REAL resolver.
      const familyPortraitByKey = nonLivePortraitMap || {};
      // Commanders = starting named characters / generals. Resolve each card's
      // savePath the SAME way resolveNonLiveCommanderInfo does: engine-exact map
      // (coord first, then name keys), then statsCache, then hash.
      const commandersNonLive = [];
      const facLc = (s) => (s || "").toLowerCase();
      for (const c of chars) {
        if (!c || !c.firstName) continue;
        const isCommander = !c.tags || c.tags.includes("leader") || c.tags.includes("heir") || c.tags.includes("named") || c.charSubType === "general";
        if (!isCommander) continue;
        // Resolve via the SHARED resolver (coord/name engine-exact map first),
        // passing the descr_strat char as the single-element `characters` list so
        // it can recover the surname/coord. `resolvable` records whether the
        // engine-exact map (NOT the hash) CAN place this commander — the new
        // checkNonLiveCommanders sub-check flags a resolvable-but-hashed card.
        const info = resolveNonLiveCommanderInfoApp(c.firstName, c.lastName, c.faction, sc, chars, nonLivePortraitMap);
        const coord = c.x != null && c.y != null ? `${c.x},${c.y}` : null;
        const resolvable = !!lookupNonLivePortraitApp(nonLivePortraitMap, c.firstName, c.lastName, c.faction, coord);
        const fn = facLc(c.firstName);
        const ln = (c.lastName || "").replace(/_/g, " ").toLowerCase();
        const fac = facLc(c.faction);
        commandersNonLive.push({
          name: `${c.firstName}${c.lastName ? " " + String(c.lastName).replace(/_/g, " ") : ""}`,
          faction: c.faction || null,
          savePath: info ? info.savePath : null,
          nameKey: `name:${fn}|${ln}|${fac}`,
          resolvable,
          // 0.9.806: does the card render ANY portrait (precise OR hash) vs go
          // BLANK? A non-null info with a firstName always hash-pools a face;
          // a null info = the bodyguard-icon/blank-box fallback (the reported bug).
          rendersPortrait: !!(info && (info.savePath || info.firstName)),
          singleName: !c.lastName,
        });
      }

      // 0.9.806: [nonlive-portrait] resolved-vs-blank counts so provincia.log
      // shows the floor is met (no commander card goes blank). `precise` = an
      // engine-exact savePath (coord/name map); `hash` = firstName-only floor
      // (deterministic culture face, same as the family tree); `blank` = the bug
      // (null info → bodyguard icon / empty box). `blank` MUST be 0 after the fix.
      {
        const precise = commandersNonLive.filter((c) => c.savePath).length;
        const blank = commandersNonLive.filter((c) => !c.rendersPortrait).length;
        const hash = commandersNonLive.length - precise - blank;
        const singleNames = commandersNonLive.filter((c) => c.singleName).length;
        const blankSamples = commandersNonLive.filter((c) => !c.rendersPortrait).slice(0, 8).map((c) => c.name);
        console.log(`[nonlive-portrait] commander cards: ${commandersNonLive.length} total → ${precise} precise (engine-exact), ${hash} hash-pool floor, ${blank} BLANK${blank ? " [" + blankSamples.join(", ") + "]" : ""}; ${singleNames} single-name chars`);
      }

      // Family roster (non-live) = descr_strat family members for all factions.
      let family = null;
      if (modFamiliesByFaction) {
        family = [];
        for (const [fac, data] of Object.entries(modFamiliesByFaction)) {
          for (const m of (data && data.members) || []) {
            // Carry the descr_strat `tags` (incl. "leader"/"heir") + isLeader so
            // the diagnostic identifies the leader the SAME way the Family Tree
            // does (FamilyTree.js crowns `tags.includes("leader")`).
            family.push({
              name: `${m.firstName || ""} ${m.lastName || ""}`.trim(),
              firstName: m.firstName, lastName: m.lastName,
              age: m.age, gender: m.gender, faction: fac,
              alive: m.alive !== false,
              tags: Array.isArray(m.tags) ? m.tags : [],
              isLeader: Array.isArray(m.tags) && m.tags.includes("leader"),
            });
          }
        }
      }
      // Faction leader (player) — the descr_strat "leader"-tagged starting char
      // (the family-tree method). Passed as a fallback hint; the tag-bearing
      // roster above lets checkFamily find it directly too.
      let factionLeader = null;
      if (playerFaction) {
        const lead = chars.find((c) => c && c.faction === playerFaction && c.tags && c.tags.includes("leader"));
        if (lead) factionLeader = { name: `${lead.firstName || "?"}${lead.lastName ? " " + String(lead.lastName).replace(/_/g, " ") : ""}`, age: typeof lead.age === "number" ? lead.age : null, alive: lead.alive !== false };
      }

      const report = runAppDiagnostics({
        label: "non-live / starting state",
        commandersNonLive,
        familyPortraitByKey,
        // No save ⇒ no live settlementFields / diplomacy; those checks INFO-skip
        // (the empty/fallback case is logged, per the standing rule).
        settlementFields: saveSettlementFields || null,
        diplomacy: null,
        playerFaction: playerFaction || null,
        expectWars: null,
        family,
        factionLeader,
        // We resolved the leader from descr_strat ⇒ assert present + adult (the
        // age-4 regression). INFO-skips if no player faction / no leader found.
        expectLeader: !!factionLeader,
        minFamilyMembers: 3,
        // Non-live has no turn/year (starting state); turnYear INFO-skips on null.
        turn: null,
      });
      logAppDiagnostics(report);
    } catch (e) {
      // Diagnostics must never break the render.
      try { console.warn("[diag] non-live self-check failed:", e && e.message); } catch (e2) { void e2; }
    }
  }, [startingCharactersFromMod, statsCache, modFamiliesByFaction, playerFaction, saveLiveArmies, saveSettlementFields]);
  const [showFactionPicker, setShowFactionPicker] = useState(false);
