        ctx.beginPath();
        ctx.arc(mapX + 0.5, mapY + 0.5, siegeR, 0, Math.PI * 2);
        ctx.strokeStyle = "rgba(255, 40, 40, 0.9)";
        ctx.lineWidth = Math.max(0.8 / totalScale, 0.2);
        ctx.stroke();
